import 'package:flutter/material.dart';
import 'nutrition_ocr_parser.dart';
class OcrReviewScreen extends StatefulWidget { const OcrReviewScreen({super.key,required this.rawText}); final String rawText; @override State<OcrReviewScreen> createState()=>_OcrReviewScreenState(); }
class _OcrReviewScreenState extends State<OcrReviewScreen>{late final NutritionOcrValues values; final fields=<String,TextEditingController>{}; @override void initState(){super.initState();values=NutritionOcrParser().parse(widget.rawText); for(final e:{'kcal':values.kcal,'kj':values.kj,'protein':values.protein,'carbs':values.carbs,'fat':values.fat,'sugar':values.sugar,'salt':values.salt}.entries)fields[e.key]=TextEditingController(text:e.value?.toString()??'');} @override void dispose(){for(final c in fields.values)c.dispose();super.dispose();} @override Widget build(BuildContext c){final recognized=fields.values.where((x)=>x.text.trim().isNotEmpty).length; return Scaffold(appBar:AppBar(title:const Text('Nährwerte prüfen')),body:ListView(padding:const EdgeInsets.all(16),children:[Text(recognized==0?'Keine Werte sicher erkannt. Bitte alle Angaben manuell prüfen.':'$recognized von ${fields.length} Werten erkannt. Bitte vor dem Speichern prüfen.',style:TextStyle(color:recognized==0?Theme.of(c).colorScheme.error:Theme.of(c).colorScheme.primary,fontWeight:FontWeight.w600)),const SizedBox(height:8),const Text('Die Werte beziehen sich auf 100 g. Dezimalwerte können korrigiert werden.'),for(final e in fields.entries)Padding(padding:const EdgeInsets.only(top:10),child:TextField(controller:e.value,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(labelText:'${e.key} / 100 g')),),const SizedBox(height:16),FilledButton(onPressed:()=>Navigator.pop(context,fields.map((k,v)=>MapEntry(k,double.tryParse(v.text.replaceAll(',','.'))))),child:const Text('Werte übernehmen'))]));}}

